import { AgentToolkit, FleetToolkit, DispatchToolkit, PaymentsToolkit } from '@wave-av/adk';

// Streams + live production (10 tools)
const studio = new AgentToolkit({ apiKey: process.env.WAVE_AGENT_KEY });
// → wave_create_stream, wave_monitor_stream, wave_create_clip,
//   wave_switch_camera, wave_show_graphic, wave_moderate_chat,
//   wave_start_captions, wave_analyze_quality, wave_mark_highlight,
//   wave_control_camera

// Voice, transcription, captions (3 tools)
const fleet = new FleetToolkit({ apiKey: process.env.WAVE_AGENT_KEY });
// → wave_speak, wave_transcribe, wave_caption

// Model routing (2 tools) — Dispatch runs on its own host
const dispatch = new DispatchToolkit({ apiKey: process.env.WAVE_AGENT_KEY });
// → wave_route, wave_list_routing_profiles

// Agent-payment rails (2 tools) — public, so no key is taken at all
const payments = new PaymentsToolkit();
// → wave_find_paid_services, wave_payment_schemes

const tools = [studio, fleet, dispatch, payments].flatMap((k) => k.toMCPTools());

import { FleetToolkit, WaveToolError } from '@wave-av/adk';

const fleet = new FleetToolkit({ apiKey: process.env.WAVE_AGENT_KEY });

try {
  const speech = await fleet.speak({ text: 'Ready when you are.' });
  await writeFile('out.mp3', speech.audio);
  console.log(speech.usage); // { meter, usageMinutes, rateLimitRemaining }

  const { transcript } = await fleet.transcribe({ url: 'https://example.com/clip.wav' });
} catch (err) {
  if (err instanceof WaveToolError && err.isRateLimited) await backOff();
  else throw err;
}

import { StreamMonitorAgent, AgentRuntime } from '@wave-av/adk';

const agent = new StreamMonitorAgent({ /* config */ });
const runtime = new AgentRuntime(agent, {
  healthPort: 8080,           // GET /health, /ready, /metrics
  heartbeatIntervalMs: 30000, // Platform heartbeat
  logLevel: 'info',           // Structured JSON logs
});

await runtime.start(); // Handles SIGTERM/SIGINT gracefully

